import pandas as pd

def count_occurrences(files: pd.DataFrame) -> pd.DataFrame:
    bull_count = files['content'].str.contains(r' bull ', regex=False).sum()
    bear_count = files['content'].str.contains(r' bear ', regex=False).sum()
    return pd.DataFrame([
        {'word': 'bull', 'count': int(bull_count)},
        {'word': 'bear', 'count': int(bear_count)}
    ])
